UPDATE Language_ru_RU
SET Text = 'Всемирный конгресс возрождается как Организация Объединённых Наций. Созывается специальная сессия, чтобы выбрать государство-хозяина этой новой могущественной дипломатической силы. Организация Объединённых Наций продолжит действовать как прежде, но обычные сессии будут чередоваться с сессиями, на которых цивилизации смогут попытаться добиться [COLOR_POSITIVE_TEXT]Мировой гегемонии[ENDCOLOR], делая возможной [COLOR_POSITIVE_TEXT]Дипломатическую победу[ENDCOLOR]. Чтобы включить такие сессии, должна быть активна [COLOR_POSITIVE_TEXT]резолюция о мировой идеологии[ENDCOLOR].'
WHERE Tag = 'TXT_KEY_LEAGUE_SPECIAL_SESSION_START_UNITED_NATIONS_HELP';
